package com.greenocean.backend;
import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;
import org.springframework.test.context.ActiveProfiles;import org.springframework.transaction.annotation.Transactional;
import org.springframework.test.web.servlet.MockMvc;import org.springframework.jdbc.core.JdbcTemplate;
import com.greenocean.backend.preference.service.*;import com.greenocean.backend.preference.dto.*;
import com.greenocean.backend.moderation.service.AdminService;import com.greenocean.backend.moderation.dto.CreatePolicyRequest;
import tools.jackson.databind.*;import java.util.*;import java.time.Instant;
import static org.assertj.core.api.Assertions.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;

@SpringBootTest(properties={"app.privacy.support-topics-enabled=true","app.governance.optional-processing-approved=true","app.governance.policy-publication-enabled=true","app.governance.rights-intake-enabled=true","app.governance.rights-owner=Synthetic-QA-owner","app.governance.rights-response-hours=48"})
@AutoConfigureMockMvc @ActiveProfiles("test") @Transactional
class PhaseJGovernanceIntegrationTest {
 @Autowired MockMvc mvc;@Autowired JdbcTemplate db;@Autowired ObjectMapper json;@Autowired jakarta.persistence.EntityManager entities;
 @Autowired PrivacyGovernanceService privacy;@Autowired PolicyPublicationService publication;@Autowired PolicyService policies;@Autowired AdminService admin;@Autowired UserPreferencesService preferences;
 @Autowired org.springframework.transaction.PlatformTransactionManager manager;
 @BeforeEach void rates(){var tx=new org.springframework.transaction.support.TransactionTemplate(manager);tx.setPropagationBehavior(3);tx.executeWithoutResult(s->db.update("DELETE FROM auth_rate_windows"));}
 record Member(UUID id,String token){}
 Member member()throws Exception{String email="j-"+UUID.randomUUID()+"@example.test";mvc.perform(post("/api/v1/auth/register").contentType("application/json").content(json.writeValueAsString(Map.of("email",email,"password","Synthetic J governance passphrase","countryCode","IR","adultSelfAttested",true,"termsVersion",1)))).andExpect(status().isCreated());PhaseAFixtures.activate(db,email);entities.clear();var login=mvc.perform(post("/api/v1/auth/login").contentType("application/json").content(json.writeValueAsString(Map.of("email",email,"password","Synthetic J governance passphrase")))).andExpect(status().isOk()).andReturn();return new Member(db.queryForObject("SELECT id FROM users WHERE email=?",UUID.class,email),json.readTree(login.getResponse().getContentAsString()).get("accessToken").asText());}
 Member staff()throws Exception{var m=member();db.update("INSERT INTO user_roles(user_id,role_id) SELECT ?,id FROM roles WHERE name='ADMIN'",m.id);return m;}
 UUID draft(Member author,String key){return admin.createPolicy(author.id,new CreatePolicyRequest(key,"Synthetic draft","QA only","<script>synthetic text, never HTML execution</script>",false,"en",Instant.now().minusSeconds(1)));}
 UUID approvedNotice()throws Exception{var a=staff();var b=staff();UUID id=draft(a,"support-topics-processing");publication.review(id,b.id,"synthetic-review-42");publication.publish(id,b.id);return id;}
 JsonNode getPrivacy(Member m)throws Exception{return json.readTree(mvc.perform(get("/api/v1/account/privacy").header("Authorization","Bearer "+m.token)).andExpect(status().isOk()).andReturn().getResponse().getContentAsString());}
 @Test @Tag("happy") void privacyReceiptDoesNotCreateTermsAcceptanceOrOptionalConsent()throws Exception{var m=member();var current=policies.published("privacy");privacy.receiveNotice(m.id,current.id());privacy.receiveNotice(m.id,current.id());var snapshot=getPrivacy(m);assertThat(snapshot.get("noticeReceipts").size()).isEqualTo(1);assertThat(snapshot.get("termsAcceptances").size()).isEqualTo(1);assertThat(snapshot.get("authorizationHistory").isEmpty()).isTrue();}
 @Test @Tag("malicious") void missingPermissionAndLegacyPreferencesNeverBecomeConsent()throws Exception{var m=member();db.update("UPDATE user_preferences SET support_topics=ARRAY['anxiety'] WHERE user_id=?",m.id);assertThat(getPrivacy(m).get("choices").get(0).get("decision").asText()).isEqualTo("UNKNOWN");assertThat(preferences.get(m.id).topicCollectionEnabled()).isFalse();assertThatThrownBy(()->privacy.decide(m.id,"SUPPORT_TOPICS","GRANTED",UUID.randomUUID())).isInstanceOf(com.greenocean.backend.common.exception.ForbiddenException.class);}
 @Test @Tag("happy") void explicitReviewedPurposeGrantPermitsTopicsAndWithdrawalClearsCurrentAndLegacyData()throws Exception{UUID notice=approvedNotice();var m=member();privacy.decide(m.id,"SUPPORT_TOPICS","GRANTED",notice);assertThat(preferences.get(m.id).topicCollectionEnabled()).isTrue();preferences.update(m.id,json.readValue("{\"supportTopics\":[\"anxiety\"]}",UpdateUserPreferencesRequest.class));db.update("UPDATE user_preferences SET legacy_support_topics=ARRAY['private legacy marker'] WHERE user_id=?",m.id);privacy.decide(m.id,"SUPPORT_TOPICS","WITHDRAWN",null);assertThat(preferences.get(m.id).supportTopics()).isEmpty();assertThat(preferences.get(m.id).legacySupportTopics()).isEmpty();assertThat(preferences.get(m.id).topicCollectionEnabled()).isFalse();assertThatThrownBy(()->preferences.update(m.id,json.readValue("{\"supportTopics\":[\"anxiety\"]}",UpdateUserPreferencesRequest.class))).isInstanceOf(com.greenocean.backend.common.exception.PreferenceValidationException.class);}
 @Test @Tag("confused") void optionalDeclineIsIdempotentAndDoesNotDisableCoreProfileAccess()throws Exception{var m=member();privacy.decide(m.id,"OPTIONAL_ANALYTICS","DENIED",null);privacy.decide(m.id,"OPTIONAL_ANALYTICS","DENIED",null);assertThat(getPrivacy(m).get("authorizationHistory").size()).isEqualTo(1);mvc.perform(get("/api/v1/profiles/me").header("Authorization","Bearer "+m.token)).andExpect(status().isOk());}
 @Test @Tag("malicious") void analyticsAndMarketingCannotBeGrantedAsDecorativePermissions()throws Exception{var m=member();for(String p:List.of("OPTIONAL_ANALYTICS","OPTIONAL_COMMUNICATIONS"))assertThatThrownBy(()->privacy.decide(m.id,p,"GRANTED",UUID.randomUUID())).isInstanceOf(com.greenocean.backend.common.exception.ForbiddenException.class);assertThat(getPrivacy(m).get("authorizationHistory").isEmpty()).isTrue();}
 @Test @Tag("malicious") void policyCreationCannotPublishAndReviewCannotBeSelfApproved()throws Exception{var author=staff();assertThatThrownBy(()->admin.createPolicy(author.id,new CreatePolicyRequest("synthetic-j","Draft","QA only","Not published",true,"en",null))).isInstanceOf(IllegalArgumentException.class);UUID id=draft(author,"synthetic-j");assertThatThrownBy(()->publication.review(id,author.id,"self-review")).isInstanceOf(com.greenocean.backend.common.exception.ForbiddenException.class);assertThatThrownBy(()->publication.publish(id,author.id)).isInstanceOf(com.greenocean.backend.common.exception.ConflictException.class);assertThat(policies.history("synthetic-j","en")).isEmpty();}
 @Test @Tag("creative") void independentReviewPublicationAndPublicHistoryKeepExactVersionAndLocale()throws Exception{var author=staff();var reviewer=staff();UUID first=draft(author,"synthetic-j-history");publication.review(first,reviewer.id,"review-one");publication.publish(first,author.id);UUID second=draft(author,"synthetic-j-history");publication.review(second,reviewer.id,"review-two");publication.publish(second,reviewer.id);assertThat(policies.published("synthetic-j-history").version()).isEqualTo(2);assertThat(policies.history("synthetic-j-history","en")).hasSize(2);assertThatThrownBy(()->policies.published("synthetic-j-history","fa")).isInstanceOf(com.greenocean.backend.common.exception.NotFoundException.class);}
 @Test @Tag("malicious") void retiredPublishedTextCannotBeRewritten()throws Exception{var author=staff();var reviewer=staff();UUID id=draft(author,"synthetic-j-immutable");publication.review(id,reviewer.id,"review-immutable");publication.publish(id,reviewer.id);assertThatThrownBy(()->db.update("UPDATE policy_documents SET content='forged' WHERE id=?",id)).isInstanceOf(org.springframework.dao.DataAccessException.class);}
 @Test @Tag("malicious") void acceptanceTimestampsCannotBeRetrofitted()throws Exception{var m=member();assertThatThrownBy(()->db.update("UPDATE policy_acceptances SET accepted_at=CURRENT_TIMESTAMP-INTERVAL '1 year' WHERE user_id=?",m.id)).isInstanceOf(org.springframework.dao.DataAccessException.class);}
 @Test @Tag("malicious") void forgedDraftNoticeReceiptAndCrossAccountPayloadAreRejectedOrOwnerBound()throws Exception{var m=member();var other=member();UUID draft=draft(staff(),"privacy");assertThatThrownBy(()->privacy.receiveNotice(m.id,draft)).isInstanceOf(com.greenocean.backend.common.exception.NotFoundException.class);mvc.perform(post("/api/v1/account/privacy/decisions").header("Authorization","Bearer "+m.token).contentType("application/json").content(json.writeValueAsString(Map.of("userId",other.id,"purpose","OPTIONAL_ANALYTICS","decision","DENIED")))).andExpect(status().isOk());assertThat(getPrivacy(other).get("authorizationHistory").isEmpty()).isTrue();mvc.perform(get("/api/v1/account/privacy/"+other.id).header("Authorization","Bearer "+m.token)).andExpect(status().is4xxClientError());}
 @Test @Tag("happy") void humanRightsIntakeIsOwnerScopedRetrySafeAndHasRealStatus()throws Exception{var m=member();var other=member();UUID key=UUID.randomUUID();var one=privacy.requestRight(m.id,"ACCESS",key);var retry=privacy.requestRight(m.id,"ACCESS",key);assertThat(one.get("id")).isEqualTo(retry.get("id"));assertThat(one.get("status")).isEqualTo("RECEIVED");assertThat(privacy.rights(other.id)).isEmpty();var reviewer=staff();publication.resolveRight((UUID)one.get("id"),reviewer.id,"IN_REVIEW","case-qa-42");assertThat(privacy.rights(m.id).getFirst().get("status")).isEqualTo("IN_REVIEW");publication.resolveRight((UUID)one.get("id"),reviewer.id,"RESOLVED","fulfilled-synthetic-case");assertThatThrownBy(()->publication.resolveRight((UUID)one.get("id"),reviewer.id,"IN_REVIEW","reopen-42")).isInstanceOf(com.greenocean.backend.common.exception.ConflictException.class);}
 @Test @Tag("confused") void duplicateOpenRightsAndConflictingRetryKindsHaveRecoverableErrors()throws Exception{var m=member();UUID key=UUID.randomUUID();privacy.requestRight(m.id,"RESTRICTION",key);assertThatThrownBy(()->privacy.requestRight(m.id,"ERASURE",key)).isInstanceOf(com.greenocean.backend.common.exception.ConflictException.class);assertThatThrownBy(()->privacy.requestRight(m.id,"RESTRICTION",UUID.randomUUID())).isInstanceOf(com.greenocean.backend.common.exception.ConflictException.class);}
 @Test @Tag("malicious") void staffRoutesStillRequireExistingStrongAuthenticationAndRole()throws Exception{var m=member();mvc.perform(post("/api/v1/admin/governance/policies/"+UUID.randomUUID()+"/review").header("Authorization","Bearer "+m.token).contentType("application/json").content("{\"reference\":\"not-authorized\"}")).andExpect(status().isForbidden());}
 @Test @Tag("happy") void exportIncludesOwnGovernanceAndErasureRemovesItWithoutLeakingAnotherOwner()throws Exception{var m=member();var other=member();privacy.decide(m.id,"OPTIONAL_ANALYTICS","DENIED",null);privacy.requestRight(m.id,"ACCESS",UUID.randomUUID());for(int n=0;n<105;n++)db.update("INSERT INTO processing_authorizations(user_id,purpose,decision) VALUES (?,'OPTIONAL_ANALYTICS','DENIED')",m.id);assertThat(getPrivacy(m).get("authorizationHistory").size()).isEqualTo(100);var archive=mvc.perform(get("/api/v1/account/archive").header("Authorization","Bearer "+m.token)).andExpect(status().isOk()).andReturn();assertThat(json.readTree(archive.getResponse().getContentAsString()).get("governance").get("rightsRequests").size()).isEqualTo(1);assertThat(json.readTree(archive.getResponse().getContentAsString()).get("governance").get("authorizationHistory").size()).isEqualTo(106);mvc.perform(delete("/api/v1/account").header("Authorization","Bearer "+m.token).contentType("application/json").content("{\"password\":\"Synthetic J governance passphrase\"}")).andExpect(status().isNoContent());assertThat(db.queryForObject("SELECT count(*) FROM processing_authorizations WHERE user_id=?",Integer.class,m.id)).isZero();assertThat(db.queryForObject("SELECT count(*) FROM data_rights_requests WHERE user_id=?",Integer.class,m.id)).isZero();assertThat(getPrivacy(other).get("authorizationHistory").isEmpty()).isTrue();}
 @Test @Tag("malicious") void olderReviewedDraftCannotReplaceANewerPublishedPolicy()throws Exception{var author=staff();var reviewer=staff();UUID old=draft(author,"synthetic-j-version-order");publication.review(old,reviewer.id,"older-review");UUID current=draft(author,"synthetic-j-version-order");publication.review(current,reviewer.id,"newer-review");publication.publish(current,reviewer.id);assertThatThrownBy(()->publication.publish(old,reviewer.id)).isInstanceOf(com.greenocean.backend.common.exception.ConflictException.class);assertThat(policies.published("synthetic-j-version-order").id()).isEqualTo(current);}
 @Test @Tag("malicious") void revokedReviewerCannotAuthorizeLaterPublication()throws Exception{var author=staff();var reviewer=staff();UUID id=draft(author,"synthetic-j-revoked-review");publication.review(id,reviewer.id,"review-before-revocation");db.update("DELETE FROM user_roles WHERE user_id=? AND role_id IN (SELECT id FROM roles WHERE name='ADMIN')",reviewer.id);assertThatThrownBy(()->publication.publish(id,author.id)).isInstanceOf(com.greenocean.backend.common.exception.ForbiddenException.class);assertThat(policies.history("synthetic-j-revoked-review","en")).isEmpty();}
 @Test @Tag("malicious") void editingReviewedDraftInvalidatesItsApproval()throws Exception{var author=staff();var reviewer=staff();UUID id=draft(author,"synthetic-j-edited-draft");publication.review(id,reviewer.id,"review-original");db.update("UPDATE policy_documents SET content='Different synthetic content' WHERE id=?",id);assertThat(db.queryForObject("SELECT review_status FROM policy_documents WHERE id=?",String.class,id)).isEqualTo("DRAFT");assertThatThrownBy(()->publication.publish(id,author.id)).isInstanceOf(com.greenocean.backend.common.exception.ConflictException.class);publication.review(id,reviewer.id,"review-new-content");publication.publish(id,author.id);assertThat(policies.published("synthetic-j-edited-draft").content()).isEqualTo("Different synthetic content");}
 @Test @Tag("malicious") void publishedReviewEvidenceCannotBeRewritten()throws Exception{var author=staff();var reviewer=staff();UUID id=draft(author,"synthetic-j-review-evidence");publication.review(id,reviewer.id,"review-auditable");publication.publish(id,author.id);assertThatThrownBy(()->db.update("UPDATE policy_documents SET review_reference='forged-review' WHERE id=?",id)).isInstanceOf(org.springframework.dao.DataAccessException.class);}
 @Test @Tag("creative") void aNewPurposeNoticeRequiresANewAffirmativeGrant()throws Exception{UUID original=approvedNotice();var m=member();privacy.decide(m.id,"SUPPORT_TOPICS","GRANTED",original);assertThat(preferences.get(m.id).topicCollectionEnabled()).isTrue();UUID replacement=approvedNotice();assertThat(preferences.get(m.id).topicCollectionEnabled()).isFalse();assertThat(getPrivacy(m).get("choices").get(0).get("currentNoticeGranted").asBoolean()).isFalse();assertThatThrownBy(()->privacy.decide(m.id,"SUPPORT_TOPICS","GRANTED",original)).isInstanceOf(com.greenocean.backend.common.exception.ForbiddenException.class);privacy.decide(m.id,"SUPPORT_TOPICS","GRANTED",replacement);assertThat(preferences.get(m.id).topicCollectionEnabled()).isTrue();}

}
